import{state}from"./state.js";import{renderAll}from"./ui.js";import{purchaseItemOnServer,requestItemPurchaseOnServer}from"./api.js";import{showToast,showConfirm,showMobileEventNotification,escapeHtml}from"./utils.js";import{applyServerFamilyData,checkLimits,flushPendingSave,getActingChildId}from"./action-helpers.js";import{triggerPurchaseAnimation}from"./motion-feedback.js";import{getMoneyLimit}from"./server-contract.js";function getShopLimitToastMessage(e){return e?e.startsWith("Месячный лимит")?`Превышен месячный лимит. ${e}`:e.startsWith("Лимит на крупные покупки")?`Уже была крупная покупка. ${e}`:e.startsWith("Лимит (")?`Лимит частоты. ${e}`:e:"Лимит исчерпан"}async function applyPurchase(e,t){await flushPendingSave();const r=await purchaseItemOnServer(e.id,t);r.success&&r.data?(applyServerFamilyData(r.data,{currentChildId:t}),renderRequests(),showMobileEventNotification(`Вы купили: ${e.name}!`,"success","Balance updated"),triggerPurchaseAnimation()):showToast(r.error||"Не удалось сохранить покупку","error")}async function sendPurchaseRequest(e,t){await flushPendingSave();const r=await requestItemPurchaseOnServer(e.id);r.success&&r.data?(applyServerFamilyData(r.data,{currentChildId:t}),renderAll(),document.querySelector('.nav__btn[data-tab="requests"]')?.click(),showMobileEventNotification("Заявка на покупку отправлена","success","Новая заявка"),triggerPurchaseAnimation()):showToast(r.error||"Не удалось отправить заявку","error")}function getBuyItemError(e){return e?0===state.children.length?"Сначала добавьте ребенка":"Сначала выберите ребенка":"Товар не найден"}export function buyItem(e){const t=state.shopItems.find(t=>t.id==e),r=getActingChildId();if(!t||!r)return showToast(getBuyItemError(t),"error");if(state.balance<t.price)return showToast("Недостаточно монет!","error");const i=getMoneyLimit(t)||0,s=checkLimits(t,i,{childIdOverride:r});if(s){if(state.isAdmin){const e=`${s}. Все равно ${state.isAdmin?"купить":"отправить заявку"}?`;return showConfirm("Лимит превышен",e,{onConfirm:()=>confirmPurchase(t,r,{mLimit:i,limitWarned:!0})})}return showToast(getShopLimitToastMessage(s),"error")}confirmPurchase(t,r,{mLimit:i})}function confirmPurchase(e,t,r={}){const{mLimit:i,limitWarned:s}=r,a=s?"Подтвердите (лимит превышен)":state.isAdmin?"Подтвердите покупку":"Отправить заявку?";let n=state.isAdmin?`Купить "${escapeHtml(e.name)}" за ${e.price}`:`"${escapeHtml(e.name)}" за ${e.price}`;n+=' <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.2rem; height: 1.2rem; vertical-align: middle;"></span>',i>0&&(n+=`<br><span style="font-size: 0.9em; color: var(--color-text-muted);">Лимит: 💶 ${i}</span>`),state.isAdmin&&(n+="?"),state.isAdmin?showConfirm(a,n,{onConfirm:()=>{applyPurchase(e,t)}}):showConfirm(a,n,{onConfirm:()=>{sendPurchaseRequest(e,t)}})}